/* From Uiverse.io by Praashoo7 - Tags: loader, smooth */
.__UIV_SCOPE__ .loader {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .heading {
  color: black;
  letter-spacing: 0.2em;
  margin-bottom: 1em;
}

.__UIV_SCOPE__ .loading {
  display: flex;
  width: 5em;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .load {
  width: 23px;
  height: 3px;
  background-color: limegreen;
  animation: 1s move_5011 infinite;
  border-radius: 5px;
  margin: 0.1em;
}

.__UIV_SCOPE__ .load:nth-child(1) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .load:nth-child(2) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .load:nth-child(3) {
  animation-delay: 0.6s;
}

@keyframes move_5011 {
  0% {
    width: 0.2em;
  }

  25% {
    width: 0.7em;
  }

  50% {
    width: 1.5em;
  }

  100% {
    width: 0.2em;
  }
}
